import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Доступные исключения - October CMS - 3.x","titleTemplate":false,"description":"October CMS включает несколько базовых типов исключений.","frontmatter":{"subtitle":"October CMS включает несколько базовых типов исключений."},"headers":[{"level":3,"title":"Application Exception","slug":"application-exception","link":"#application-exception","children":[]},{"level":3,"title":"System Exception","slug":"system-exception","link":"#system-exception","children":[]},{"level":3,"title":"Not Found Exception","slug":"not-found-exception","link":"#not-found-exception","children":[]},{"level":3,"title":"Validation Exception","slug":"validation-exception","link":"#validation-exception","children":[]},{"level":3,"title":"AJAX Exception","slug":"ajax-exception","link":"#ajax-exception","children":[]},{"level":2,"title":"Обработка исключений","slug":"обработка-исключении","link":"#обработка-исключении","children":[{"level":3,"title":"Где размещать обработчики ошибок","slug":"где-размещать-обработчики-ошибок","link":"#где-размещать-обработчики-ошибок","children":[]}]},{"level":2,"title":"HTTP-исключения","slug":"http-исключения","link":"#http-исключения","children":[{"level":3,"title":"Пользовательская страница ошибки","slug":"пользовательская-страница-ошибки","link":"#пользовательская-страница-ошибки","children":[]}]}],"relativePath":"3.x/ru/extend/system/exceptions.md","filePath":"3.x/ru/extend/system/exceptions.md"}'),r={name:"3.x/ru/extend/system/exceptions.md"};function u(d,n,k,h,x,g){const e=a("pre-heading"),t=a("post-heading");return o(),c("div",null,[s(e),n[0]||(n[0]=l("h1",null,"Доступные исключения",-1)),s(t),n[1]||(n[1]=i(`<h3 id="application-exception"><a href="#application-exception" class="header-anchor">#</a> Application Exception</h3><p>Класс <code>October\\Rain\\Exception\\ApplicationException</code>, с псевдонимом <code>ApplicationException</code>, является наиболее распространённым типом исключений, используемым когда простое условие приложения не выполнено.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ApplicationException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;You must be logged in to do that!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Сообщение об ошибке будет упрощено и никогда не будет содержать конфиденциальную информацию, такую как PHP-файл и номер строки.</p><h3 id="system-exception"><a href="#system-exception" class="header-anchor">#</a> System Exception</h3><p>Класс <code>October\\Rain\\Exception\\SystemException</code>, с псевдонимом <code>SystemException</code>, используется для ошибок, критичных для функционирования системы, и всегда записывается в журнал.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">SystemException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Unable to contact the mail server API&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При выбросе этого исключения отображается подробное сообщение об ошибке с файлом и номером строки, где оно произошло.</p><h3 id="not-found-exception"><a href="#not-found-exception" class="header-anchor">#</a> Not Found Exception</h3><p>Класс <code>October\\Rain\\Exception\\NotFoundException</code>, с псевдонимом <code>NotFoundException</code>, используется для ошибок, возникающих при обнаружении отсутствующей записи.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Record not found&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При выбросе этого исключения стандартный ответ изменится для отображения ближайшей страницы «не найдено» с HTTP-кодом 404.</p><h3 id="validation-exception"><a href="#validation-exception" class="header-anchor">#</a> Validation Exception</h3><p>Класс <code>October\\Rain\\Exception\\ValidationException</code>, с псевдонимом <code>ValidationException</code>, используется для ошибок, связанных непосредственно с отправкой формы и невалидным полем. Сообщение должно содержать массив с полями и сообщениями об ошибках.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Sorry that username is already taken!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете передать экземпляр <a href="./../services/validation.html">сервиса валидации</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$validation</span> <span class="token operator">=</span> <span class="token class-name static-context">Validator</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token operator">-&gt;</span><span class="token function">fails</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>При выбросе этого исключения <a href="./ajax.html">AJAX-фреймворк</a> предоставит эту информацию в удобном формате и установит фокус на первое невалидное поле.</p><h3 id="ajax-exception"><a href="#ajax-exception" class="header-anchor">#</a> AJAX Exception</h3><p>Класс <code>October\\Rain\\Exception\\AjaxException</code>, с псевдонимом <code>AjaxException</code>, считается «умной ошибкой» и возвращает HTTP-код 406. Это позволяет передавать содержимое ответа, как если бы это был успешный ответ.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#flashMessages&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При выбросе этого исключения <a href="./ajax.html">AJAX-фреймворк</a> будет следовать стандартному процессу обработки ошибок, но также обновит указанные частичные представления.</p><h2 id="обработка-исключении"><a href="#обработка-исключении" class="header-anchor">#</a> Обработка исключений</h2><p>Все исключения обрабатываются классом <code>October\\Rain\\Foundation\\Exception\\Handler</code>. Этот класс содержит два метода: <code>report</code> и <code>render</code>, которые определяют, должна ли ошибка записываться в журнал и как отвечать на ошибку.</p><p>Однако при необходимости вы можете указать пользовательские обработчики с помощью метода <code>App::error</code>. Обработчики вызываются на основе type-hint обрабатываемого исключения. Например, вы можете создать обработчик, который обрабатывает только экземпляры <code>RuntimeException</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">RuntimeException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Handle the exception...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если обработчик исключений возвращает ответ, этот ответ будет отправлен в браузер, и другие обработчики ошибок вызваны не будут.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">InvalidUserException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Sorry! Something is wrong with this account!&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для прослушивания фатальных ошибок PHP можно проверить тип исключения Error:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">Error</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если у вас несколько обработчиков исключений, они должны быть определены от наиболее общих к наиболее специфичным. Так, например, обработчик всех исключений типа <code>Exception</code> должен быть определён перед пользовательским типом исключения, таким как <code>SystemException</code>.</p><h3 id="где-размещать-обработчики-ошибок"><a href="#где-размещать-обработчики-ошибок" class="header-anchor">#</a> Где размещать обработчики ошибок</h3><p>Регистрация обработчиков ошибок обычно относится к категории загрузочного кода. Другими словами, они подготавливают ваше приложение к обработке запросов и обычно должны выполняться до вызова маршрута или контроллера. Наиболее распространённое место — метод <code>boot</code> <a href="./../extending.html">файла регистрации плагина</a>. Альтернативно плагины могут предоставить файл <strong>init.php</strong> в директории плагина для размещения регистрации обработчиков ошибок.</p><h2 id="http-исключения"><a href="#http-исключения" class="header-anchor">#</a> HTTP-исключения</h2><p>Некоторые исключения описывают HTTP-коды ошибок сервера. Например, это может быть ошибка «страница не найдена» (404), «ошибка авторизации» (401) или сгенерированная разработчиком ошибка 500. Для генерации такого ответа из любого места приложения используйте следующее.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>abort</code> немедленно выбросит исключение, которое будет обработано обработчиком исключений. Опционально можно указать текст ответа.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">403</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Unauthorized action.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Этот метод может использоваться в любой момент жизненного цикла запроса. Также существует сопутствующий <a href="./../../markup/function/abort.html">Twig-фильтр для прерывания запросов</a>.</p><h3 id="пользовательская-страница-ошибки"><a href="#пользовательская-страница-ошибки" class="header-anchor">#</a> Пользовательская страница ошибки</h3><p>По умолчанию любые ошибки отображаются с подробной страницей ошибки, содержащей содержимое файла, номер строки и трассировку стека. Вы можете отобразить пользовательскую страницу ошибки, установив значение конфигурации <code>debug</code> в <strong>false</strong> в скрипте <code>config/app.php</code> и создав страницу с URL <code>/error</code>.</p>`,41))])}const f=p(r,[["render",u]]);export{v as __pageData,f as default};
